def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    try:
        from datetime import datetime, timezone, timedelta
        if tz is None:
            # Assuming LocalTime if no timezone is provided
            return datetime.fromtimestamp(nanoseconds / 1e9).time()
        else:
            # Assuming Time with timezone if timezone is provided
            if not isinstance(tz, (timezone, str)):
                raise ValueError("tz must be a datetime.timezone or a string representing a timezone")
            if isinstance(tz, str):
                import pytz
                tz = pytz.timezone(tz)
            return datetime.fromtimestamp(nanoseconds / 1e9, tz).time()
    except Exception as e:
        raise RuntimeError(f"Error hydrating time: {e}")

