def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        if not isinstance(classes, list):
            raise ValueError("Input must be a list of classes.")

        # Create a set to track seen classes and a list for the minimal bases
        seen = set()
        minimal = []

        # Iterate over the classes in reverse order to maintain the MRO
        for cls in reversed(classes):
            if cls not in seen:
                # Add the class to the minimal list and mark it as seen
                minimal.append(cls)
                seen.add(cls)
                # Add all superclasses of the current class to the seen set
                for base in cls.__bases__:
                    seen.add(base)

        # Return the minimal list in the original order
        return list(reversed(minimal))

    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

