    try:
        for point in self.points:
            coord_str = separator.join(map(str, point[0]))
            value_str = separator.join(map(str, point[1]))
            lines.append(f"{coord_str}{separator}{value_str}")
    except AttributeError:
        raise AttributeError("The object does not have a 'points' attribute.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while converting to CSV: {e}")

    return "\n".join(lines)

