def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not app or not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Invalid application object or missing manifest")

        default_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {"type": "string"},
                                    "status": {"type": "string"},
                                    "lastProbeTime": {"type": "string"},
                                    "lastTransitionTime": {"type": "string"},
                                    "reason": {"type": "string"},
                                    "message": {"type": "string"}
                                },
                                "required": ["type", "status"]
                            }
                        }
                    }
                }
            }
        }

        observer_schema = app.spec.observer_schema or {}

        for resource_name, resource in app.spec.manifest.items():
            if resource_name not in observer_schema:
                observer_schema[resource_name] = default_schema

        app.spec.observer_schema = observer_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

