def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not isinstance(dicts, (list, tuple)):
        raise TypeError("The input must be a list or tuple of dictionaries.")

    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements of the input iterable must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All dictionary values must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

