def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must be a list of single-character strings.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer or None.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    result.reverse()

    if padding is not None:
        result = [alphabet[0]] * (padding - len(result)) + result

    return ''.join(result)

