def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if not isinstance(config_filenames, (list, tuple)):
        raise ValueError("config_filenames must be a list or tuple of filenames.")
    if overrides is not None and not isinstance(overrides, dict):
        raise ValueError("overrides must be a dictionary or None.")
    if not isinstance(resolve_env, bool):
        raise ValueError("resolve_env must be a boolean.")

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=(), exc_info=True))
            continue
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"JSON decode error in {filename}: {e}", args=(), exc_info=True))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        if overrides:
            config.update(overrides)

        config_dict[filename] = config

    return config_dict, log_records

